def find_zero_block(grid):
    """The bounding box (r0, r1, c0, c1) of all 0 cells."""
    z = [(i, j) for i, r in enumerate(grid) for j, v in enumerate(r) if v == 0]
    rs = [i for i, _ in z]; cs = [j for _, j in z]
    return min(rs), max(rs), min(cs), max(cs)

